std::string s_int = "123";
std::string s_double = "3.14";
int i_result = 0;
double d_result = 0.0;

try {
    // Basic conversions
    i_result = std::stoi(s_int);
    d_result = std::stod(s_double);

    // Conversion with remainder check (pos points to first unconverted char)
    size_t pos;
    long l_result = std::stol("99999X", &pos);
}
catch (const std::invalid_argument& e) {
    // Input contains non-convertible characters
}
catch (const std::out_of_range& e) {
    // Value exceeds target type limits (e.g., long string to int)
}
